"""Inventory & Orders JSON API ported to the pattern. Paths, methods, status codes and JSON keys are unchanged."""

import logging

from flask import Blueprint, abort, jsonify, request
from sqlalchemy import text
from sqlalchemy.exc import IntegrityError

from .db import execute, fetch_all, fetch_one, transaction
from .web import float_field, int_field, json_body, require_admin_token, utc_now_iso

bp = Blueprint("api", __name__)
log = logging.getLogger(__name__)


@bp.get("/api/items")
def list_items():
    search = request.args.get("search")
    if search:
        # SQL injection fix: the search term is a bound parameter, never part of the SQL text.
        # LOWER() keeps SQLite's case-insensitive LIKE behaviour on PostgreSQL.
        rows = fetch_all("SELECT * FROM items WHERE LOWER(name) LIKE LOWER(:pattern) ORDER BY id", pattern=f"%{search}%")
    else:
        rows = fetch_all("SELECT * FROM items ORDER BY id")
    return jsonify(rows)


@bp.post("/api/items")
def create_item():
    data = json_body("sku", "name")
    params = {
        "sku": data["sku"],
        "name": data["name"],
        "quantity": int_field(data, "quantity", default=0),
        "price": float_field(data, "price", default=0),
    }
    try:
        with transaction() as conn:
            # RETURNING id works on SQLite and PostgreSQL (cursor.lastrowid does not on PostgreSQL).
            new_id = conn.execute(
                text(
                    "INSERT INTO items (sku, name, quantity, price) VALUES (:sku, :name, :quantity, :price) RETURNING id"
                ),
                params,
            ).scalar_one()
    except IntegrityError:
        abort(409, "sku already exists")
    log.info("created item", extra={"sku": data["sku"]})
    return jsonify({"id": new_id}), 201


@bp.get("/api/items/<int:item_id>")
def get_item(item_id: int):
    row = fetch_one("SELECT * FROM items WHERE id = :id", id=item_id)
    return (jsonify(row), 200) if row else (jsonify({"error": "not found"}), 404)


@bp.put("/api/items/<int:item_id>")
def update_item(item_id: int):
    data = json_body("quantity", "price")
    params = {
        "quantity": int_field(data, "quantity", minimum=0),
        "price": float_field(data, "price", minimum=0),
        "id": item_id,
    }
    execute("UPDATE items SET quantity = :quantity, price = :price WHERE id = :id", **params)
    return jsonify({"ok": True})


@bp.delete("/api/items/<int:item_id>")
def delete_item(item_id: int):
    require_admin_token("X-Admin-Token")  # the key now comes from the ADMIN_TOKEN secret
    try:
        execute("DELETE FROM items WHERE id = :id", id=item_id)
    except IntegrityError:
        abort(409, "item has orders")
    return jsonify({"ok": True})


@bp.post("/api/orders")
def create_order():
    data = json_body("item_id", "quantity")
    item_id, quantity = int_field(data, "item_id", minimum=1), int_field(data, "quantity", minimum=1)
    with transaction() as conn:
        # Atomic conditional decrement: never oversells, even with concurrent requests across many pods.
        updated = conn.execute(
            text("UPDATE items SET quantity = quantity - :quantity WHERE id = :item_id AND quantity >= :quantity"),
            {"quantity": quantity, "item_id": item_id},
        ).rowcount
        if updated != 1:
            return jsonify({"error": "insufficient stock"}), 409
        order_id = conn.execute(
            text(
                "INSERT INTO orders (item_id, quantity, created_at) "
                "VALUES (:item_id, :quantity, :created_at) RETURNING id"
            ),
            {"item_id": item_id, "quantity": quantity, "created_at": utc_now_iso()},
        ).scalar_one()
    log.info("order created", extra={"order_id": order_id, "item_id": item_id, "quantity": quantity})
    return jsonify({"order_id": order_id}), 201

