    assert [r["sku"] for r in rows] == ["SKU-1001"]


def test_search_sql_injection_is_inert(client, seeded):
    response = client.get("/api/items", query_string={"search": "' OR '1'='1"})
    assert response.status_code == 200 and response.get_json() == []


def test_create_then_get(client):
    response = client.post("/api/items", json={"sku": "SKU-9999", "name": "Test Item", "quantity": 100, "price": 9.99})
    assert response.status_code == 201
    new_id = response.get_json()["id"]
    assert client.get(f"/api/items/{new_id}").get_json()["name"] == "Test Item"


def test_create_validates_input(client):
    assert client.post("/api/items", json={"sku": "X"}).status_code == 400  # missing name
    assert client.post("/api/items", json={"name": "t"}).status_code == 400  # missing sku
    assert client.post("/api/items", json={"sku": "X", "name": "t", "quantity": "many"}).status_code == 400


def test_duplicate_sku_is_a_conflict(client, seeded):
    assert client.post("/api/items", json={"sku": "SKU-1001", "name": "dup"}).status_code == 409


def test_get_unknown_returns_404(client):
    response = client.get("/api/items/999")
    assert response.status_code == 404 and response.get_json() == {"error": "not found"}


def test_update_item(client, seeded):
    response = client.put("/api/items/1", json={"quantity": 500, "price": 0.50})
    assert response.status_code == 200 and response.get_json() == {"ok": True}
    item = client.get("/api/items/1").get_json()
    assert item["quantity"] == 500 and item["price"] == 0.50


def test_update_validates_input(client, seeded):
    assert client.put("/api/items/1", json={"quantity": -1, "price": 0.50}).status_code == 400
    assert client.put("/api/items/1", json={"quantity": 10, "price": -5.0}).status_code == 400


def test_delete_requires_admin_token(client, seeded, admin_token):
    assert client.delete("/api/items/6").status_code == 403
    assert client.delete("/api/items/6", headers={"X-Admin-Token": "wrong"}).status_code == 403
    response = client.delete("/api/items/6", headers={"X-Admin-Token": admin_token})
    assert response.status_code == 200 and response.get_json() == {"ok": True}


def test_delete_item_with_orders_fails(client, seeded, admin_token):
    # First create an order for item 1
    client.post("/api/orders", json={"item_id": 1, "quantity": 1})
    # Try to delete it
    response = client.delete("/api/items/1", headers={"X-Admin-Token": admin_token})
    assert response.status_code == 409 and "item has orders" in response.get_json()["error"]


def test_order_decrements_quantity(client, seeded):
    response = client.post("/api/orders", json={"item_id": 2, "quantity": 50})
    assert response.status_code == 201 and "order_id" in response.get_json()
    assert client.get("/api/items/2").get_json()["quantity"] == 900  # 950 - 50 = 900


def test_order_never_oversells(client, seeded):
    # Item 3 has quantity 7
    response = client.post("/api/orders", json={"item_id": 3, "quantity": 10})
    assert response.status_code == 409 and response.get_json() == {"error": "insufficient stock"}
    assert client.get("/api/items/3").get_json()["quantity"] == 7  # unchanged
    assert client.post("/api/orders", json={"item_id": 3, "quantity": -1}).status_code == 400  # validate min


def test_concurrent_orders_never_oversell(app, seeded):
    def order(_):
        return app.test_client().post("/api/orders", json={"item_id": 5, "quantity": 1}).status_code

    # Item 5 starts with quantity 5
    with ThreadPoolExecutor(max_workers=8) as pool:
        codes = list(pool.map(order, range(8)))
    # Only 5 successful orders, 3 should fail
    assert codes.count(201) == 5 and codes.count(409) == 3
    # Final quantity should be 0
    assert app.test_client().get("/api/items/5").get_json()["quantity"] == 0
